using FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.ValueObjects;

namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.Commands;

/// <summary>
///     Command to register a field event or a clinical intervention. Required values are empty when the client
///     omitted them or sent an unknown operation type, so that every missing field can be reported together.
/// </summary>
/// <param name="OperationId">The identifier generated by the client, reused on every retry.</param>
/// <param name="AnimalId">The animal the operation was applied to.</param>
/// <param name="Type">The kind of operation, or <see langword="null"/> when missing or unknown.</param>
/// <param name="OccurredAt">The instant the operation happened.</param>
/// <param name="Observation">A free-text observation, if any.</param>
/// <param name="Product">The administered product, only for clinical interventions.</param>
/// <param name="Dose">The administered dose, only for clinical interventions.</param>
public sealed record RegisterLivestockOperationCommand(
    Guid OperationId,
    Guid? AnimalId,
    OperationType? Type,
    DateTimeOffset? OccurredAt,
    string? Observation,
    string? Product,
    string? Dose);
